int max_shield(int s[], int n) {
    int best = s[0];
    for (int i = 1; i < n; i++) {
        if (s[i] > best) {
            best = s[i];
        }
    }
    return best;
}

int max_shield(int s[], int n) {
    int best = s[0];
    int i = 1;
    while (i < n) {
        if (s[i] > best) {
            best = s[i];
        }
        i++;
    }
    return best;
}

int max_shield(int s[], int n) {
    int best = s[n - 1];
    int i;
    for (i = 0; i < n - 1; i++) {
        if (s[i] > best) {
            best = s[i];
        }
    }
    return best;
}

